document.addEventListener('DOMContentLoaded', function () { var toggle = document.querySelector('.nav-toggle'); var menu = document.querySelector('nav.primary-nav ul'); if (toggle && menu) { toggle.addEventListener('click', function () { menu.classList.toggle('open'); var expanded = toggle.getAttribute('aria-expanded') === 'true'; toggle.setAttribute('aria-expanded', String(!expanded)); }); } var dateEl = document.querySelector('[data-current-date]'); if (dateEl) { var today = new Date(); var options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }; dateEl.textContent = today.toLocaleDateString('en-IN', options); } });
